/**
 * Utility to repair and sanitize malformed JSON strings, especially those
 * generated by LLMs (e.g. Gemini, ChatGPT) containing unescaped LaTeX backslashes,
 * trailing commas, markdown code blocks, or control characters.
 */

// LaTeX command prefixes starting with 't' that should not be parsed as JSON \t (tab)
const LATEX_T_KEYWORDS = [
  'textbf', 'textit', 'texttt', 'textrm', 'textsc', 'textsf', 'textmd', 'textup', 'textcolor', 'text',
  'times', 'theta', 'Theta', 'tan', 'tanh', 'tau', 'trianglelefteq', 'trianglerighteq', 'triangleq', 'triangle',
  'to', 'tilde', 'top', 'tfrac', 'tag', 'tiny', 'therefore', 'thicksim', 'thickapprox',
  'twoheadrightarrow', 'twoheadleftarrow',
];

// LaTeX command prefixes starting with 'n' that should not be parsed as JSON \n (newline)
const LATEX_N_KEYWORDS = [
  'normalsize', 'natural', 'nexists', 'nearrow', 'nwarrow', 'notin', 'nabla',
  'nvdash', 'nvDash', 'nprec', 'nsucc', 'neq', 'not', 'nu', 'ni', 'ne',
];

function isHex(c: string): boolean {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

function isLetter(c: string): boolean {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

function matchesLatexKeyword(s: string, keywords: string[]): boolean {
  for (const kw of keywords) {
    if (s.startsWith(kw)) {
      if (s.length === kw.length || !isLetter(s[kw.length])) {
        return true;
      }
    }
  }
  return false;
}

export function extractJsonFromMarkdown(raw: string): string {
  let s = raw.trim();
  if (s.startsWith('```json')) {
    s = s.slice(7);
  } else if (s.startsWith('```')) {
    s = s.slice(3);
  }
  if (s.endsWith('```')) {
    s = s.slice(0, -3);
  }
  s = s.trim();

  const firstBracket = s.indexOf('[');
  const firstBrace = s.indexOf('{');
  let first = -1;
  if (firstBracket !== -1 && (firstBrace === -1 || firstBracket < firstBrace)) {
    first = firstBracket;
  } else if (firstBrace !== -1) {
    first = firstBrace;
  }

  const lastBracket = s.lastIndexOf(']');
  const lastBrace = s.lastIndexOf('}');
  let last = -1;
  if (lastBracket !== -1 && (lastBrace === -1 || lastBracket > lastBrace)) {
    last = lastBracket;
  } else if (lastBrace !== -1) {
    last = lastBrace;
  }

  if (first !== -1 && last !== -1 && first < last) {
    return s.slice(first, last + 1);
  }
  return s;
}

export function cleanAndRepairJson(raw: string): string {
  const s = extractJsonFromMarkdown(raw);
  let result = '';
  let inString = false;
  const n = s.length;

  for (let i = 0; i < n; i++) {
    const c = s[i];

    if (!inString) {
      if (c === '"') {
        inString = true;
        result += c;
      } else if (c === ',') {
        let j = i + 1;
        while (j < n && (s[j] === ' ' || s[j] === '\t' || s[j] === '\n' || s[j] === '\r')) {
          j++;
        }
        if (j < n && (s[j] === '}' || s[j] === ']')) {
          continue; // omit trailing comma
        }
        result += c;
      } else {
        result += c;
      }
      continue;
    }

    // Inside JSON string
    if (c === '"') {
      inString = false;
      result += c;
    } else if (c === '\n' || c === '\r') {
      if (c === '\r' && i + 1 < n && s[i + 1] === '\n') {
        i++;
      }
      result += '\\n';
    } else if (c === '\t') {
      result += '\\t';
    } else if (c === '\\') {
      if (i + 1 >= n) {
        result += '\\\\';
        break;
      }
      const next = s[i + 1];
      if (next === '"' || next === '\\' || next === '/') {
        result += '\\' + next;
        i++;
      } else if (next === 'u') {
        if (i + 5 < n && isHex(s[i + 2]) && isHex(s[i + 3]) && isHex(s[i + 4]) && isHex(s[i + 5])) {
          result += '\\u';
          i++;
        } else {
          result += '\\\\';
        }
      } else if (next === 'f' || next === 'b') {
        if (i + 2 < n && isLetter(s[i + 2])) {
          // LaTeX: \frac, \beta, \bar, \begin...
          result += '\\\\';
        } else {
          result += '\\' + next;
          i++;
        }
      } else if (next === 'r') {
        if (i + 2 < n && isLetter(s[i + 2])) {
          // LaTeX: \right, \rho...
          result += '\\\\';
        } else {
          result += '\\' + next;
          i++;
        }
      } else if (next === 't') {
        if (matchesLatexKeyword(s.slice(i + 1), LATEX_T_KEYWORDS)) {
          // LaTeX: \text, \times, \theta, \tan...
          result += '\\\\';
        } else {
          result += '\\' + next;
          i++;
        }
      } else if (next === 'n') {
        if (matchesLatexKeyword(s.slice(i + 1), LATEX_N_KEYWORDS)) {
          // LaTeX: \neq, \notin, \nabla...
          result += '\\\\';
        } else {
          result += '\\' + next;
          i++;
        }
      } else {
        // Any other invalid escape (e.g. \sqrt, \alpha, \pm, \left, \cdot, \in, \parallel, \ge, \{, \})
        result += '\\\\';
      }
    } else {
      result += c;
    }
  }

  return result;
}

export function safeJsonParse<T = any>(raw: string): T {
  const cleaned = cleanAndRepairJson(raw);
  try {
    return JSON.parse(cleaned) as T;
  } catch (err: any) {
    // If repaired JSON still fails, try original raw just in case
    try {
      return JSON.parse(raw.trim()) as T;
    } catch {
      throw new Error(`Dữ liệu JSON không hợp lệ: ${err.message || 'Lỗi cú pháp'}`);
    }
  }
}
